def _is_production_like() -> bool:
    """Return True if the runtime looks like a public-facing deployment.

    The heuristic is intentionally conservative: any deployment with a
    non-loopback bind address is treated as production. The Werkzeug
    debugger is forbidden on those binds.
    """
    bind = os.environ.get("QV_BIND_HOST", "0.0.0.0")
    return bind not in ("127.0.0.1", "localhost", "::1")


if __name__ == "__main__":
    main()

def _is_production() -> bool:
    """Return True unless the operator explicitly opts into dev mode."""
    env = os.environ.get("QV_ENV", "").lower()
    if env in ("dev", "development"):
        return False
    if env in ("prod", "production"):
        return True
    # No explicit env: fall back to the well-known Flask convention.
    return os.environ.get("FLASK_ENV", "production") == "production"

func main() {
    gateway := flag.String("g", "", "Dirección IP del gateway")
    target := flag.String("t", "", "Dirección IP del target")
    message := flag.String("m", "¡Hola, este es un mensaje secreto!", "Mensaje a cifrar")
    flag.Parse()

    fmt.Printf("Gateway: %s, Target: %s, Message: %s\n", *gateway, *target, *message)

    conn, err := net.Dial("tcp", *target+":12345")
    if err != nil {
        fmt.Printf("Error al conectar al target %s:12345: %v\n", *target, err)
        return
    }
    defer conn.Close()

    // Inicializa ML-KEM-512
    kem := oqs.KeyEncapsulation{}
    defer kem.Clean()
    err = kem.Init("ML-KEM-512", nil)
    if err != nil {
        fmt.Printf("Error al inicializar KEM: %v\n", err)
        return
    }

    // Recibe la clave pública (800 bytes)
    publicKey := make([]byte, kem.Details().LengthPublicKey)
    n, err := conn.Read(publicKey)
    if err != nil {
        fmt.Printf("Error al recibir publicKey: %v\n", err)
        return
    }
    fmt.Printf("Recibido publicKey (%d bytes): %x\n", n, publicKey)

    // Encapsula el secreto compartido
    ciphertext, sharedSecret, err := kem.EncapSecret(publicKey)
    if err != nil {
        fmt.Printf("Error al encapsular: %v\n", err)
        return
    }
    fmt.Printf("Enviando ciphertext (%d bytes): %x\n", len(ciphertext), ciphertext)

def _now_utc() -> datetime:
    """Return the current time as a timezone-aware UTC datetime.

    Avoids the deprecated ``datetime.utcnow()`` which returns a naive
    value and triggers a DeprecationWarning in Python 3.12+.
    """
    return datetime.now(timezone.utc)

def _is_code_valid(self, expires_at) -> bool:
    """Return True if a verification code has not yet expired."""
    if not expires_at:
        return False
    try:
        if isinstance(expires_at, str):
            expires_dt = datetime.fromisoformat(expires_at)
        else:
            expires_dt = expires_at

        if expires_dt.tzinfo is None:
            expires_dt = pytz.utc.localize(expires_dt)

        return _now_utc() <= expires_dt
    except (ValueError, TypeError):
        return False

