def _has_phone_unique_constraint(self) -> bool:
    """Return True if the ``users.phone`` column is UNIQUE.

    SQLite does not expose UNIQUE column constraints via ``PRAGMA
    table_info``; the only reliable signal is the auto-index that
    SQLite materialises for any ``UNIQUE`` column (``sqlite_autoindex_users_N``).
    """
    with sqlite3.connect(self.db_path) as db:
        for row in db.execute("PRAGMA index_list('users')").fetchall():
            idx_name = row[1]
            if not idx_name.startswith("sqlite_autoindex_users_"):
                continue
            cols = [
                r[2] for r in db.execute(
                    f"PRAGMA index_info('{idx_name}')"
                ).fetchall()
            ]
            if cols == ["phone"]:
                return True
    return False

def _parse_datetime(value) -> Optional[datetime]:
    """Parse a stored timestamp into a datetime, tolerating the format.

    Args:
        value: A datetime, an ISO-like timestamp string, or None.

    Returns:
        The parsed datetime, or None when the value is empty or unparseable.
    """
    if not value:
        return None
    if isinstance(value, datetime):
        return value
    for fmt in ('%Y-%m-%d %H:%M:%S.%f%z', '%Y-%m-%d %H:%M:%S%z', '%Y-%m-%d %H:%M:%S'):
        try:
            return datetime.strptime(value, fmt)
        except (ValueError, TypeError):
            continue
    try:
        return datetime.fromisoformat(value)
    except (ValueError, TypeError):
        return None

class DoctorReport:
    """Accumulated check results with derived exit status."""

    results: list[CheckResult] = field(default_factory=list)

def add(self, result: CheckResult) -> None:
    """Append one check result."""
    self.results.append(result)

@property

def failures(self) -> list[CheckResult]:
    """Return every failing check."""
    return [item for item in self.results if not item.ok]

@property

def exit_code(self) -> int:
    """Return 0 when every check passes, 1 otherwise."""
    return 0 if not self.failures else 1

def load_env_file(path: Path) -> dict[str, str]:
    """Parse a dotenv file into a dict without third-party imports."""
    values: dict[str, str] = {}
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return values
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        key = key.strip()
        value = value.strip().strip("'").strip('"')
        if key:
            values[key] = value
    return values

def check_module(name: str) -> CheckResult:
    """Verify one Python module imports cleanly."""
    if str(_PROJECT_ROOT) not in sys.path:
        sys.path.insert(0, str(_PROJECT_ROOT))
    try:
        importlib.import_module(name)
    except Exception as exc:
        return CheckResult(
            name=f"python:{name}",
            ok=False,
            detail=f"{type(exc).__name__}: {exc}",
            remedy="Run `make doctor-fix` (reinstalls requirements.txt).",
        )
    return CheckResult(name=f"python:{name}", ok=True, detail="import ok")

def check_binary(name: str, env_override: str = "") -> CheckResult:
    """Verify one system binary resolves via PATH or an override path."""
    candidates = [env_override] if env_override else []
    candidates.append(name)
    for candidate in candidates:
        if not candidate:
            continue
        if "/" in candidate:
            if Path(candidate).is_file():
                return CheckResult(
                    name=f"bin:{name}", ok=True, detail=candidate
                )
            continue
        found = shutil.which(candidate)
        if found:
            return CheckResult(name=f"bin:{name}", ok=True, detail=found)
    return CheckResult(
        name=f"bin:{name}",
        ok=False,
        detail="not found on PATH",
        remedy="Run `make doctor-fix` or contact your administrator.",
    )

