def collect_local_assets() -> dict[str, str]:
    """Hash every first-party script and stylesheet under ``static/``."""
    assets: dict[str, str] = {}
    for path in sorted(STATIC_DIR.rglob("*")):
        if not path.is_file():
            continue
        if path.name == "sri_manifest.json":
            continue
        if path.suffix.lower() not in LOCAL_SUFFIXES:
            continue
        relative = path.relative_to(STATIC_DIR).as_posix()
        assets[relative] = compute_file_sri(path, SRI_ALGORITHM)
    return assets

def fetch_cdn_assets() -> dict[str, str]:
    """Download every pinned CDN URL and hash its exact bytes."""
    assets: dict[str, str] = {}
    for url in PINNED_CDN_URLS:
        with urllib.request.urlopen(url, timeout=30) as response:
            body = response.read()
        assets[url] = compute_sri(body, SRI_ALGORITHM)
    return assets

def build_manifest(cdn: dict[str, str], local: dict[str, str]) -> dict:
    """Assemble the deterministic manifest document."""
    return {
        "version": 1,
        "algorithm": SRI_ALGORITHM,
        "assets": dict(sorted(local.items())),
        "cdn": dict(sorted(cdn.items())),
    }

def render_manifest(manifest: dict) -> str:
    """Render the manifest deterministically with a trailing newline."""
    return json.dumps(manifest, indent=2, sort_keys=True) + "\n"

def _is_equivalent_bool(tokens: list[tokenize.TokenInfo], index: int) -> bool:
    if index < 2:
        return False
    previous = tokens[index - 1]
    before = tokens[index - 2]
    return (
        previous.type == tokenize.OP
        and previous.string == "="
        and before.string in SKIP_BOOL_KEYWORDS
    )

def discover_mutations(path: Path, source: str) -> list[Mutation]:
    """Return every token-level mutation the harness can apply to a module."""
    mutations: list[Mutation] = []
    reader = io.StringIO(source).readline
    tokens = [
        token
        for token in tokenize.generate_tokens(reader)
        if token.type not in IGNORED_TOKEN_TYPES
    ]
    for index, token in enumerate(tokens):
        if token.type not in NAME_TOKEN_TYPES and token.type not in KEYWORD_TOKEN_TYPES:
            continue
        if token.string in {"True", "False"} and _is_equivalent_bool(tokens, index):
            continue
        replacement = OPERATOR_MUTATIONS.get(token.string)
        if replacement is None:
            continue
        mutations.append(
            Mutation(
                path=path,
                line=token.start[0],
                column=token.start[1],
                original=token.string,
                replacement=replacement,
                description=f"{path.name}:{token.start[0]} {token.string} -> {replacement}",
            )
        )
    return mutations

def apply_mutation(source: str, mutation: Mutation) -> str:
    """Return source with one token replaced at its exact position."""
    lines = source.splitlines(keepends=True)
    index = mutation.line - 1
    line = lines[index]
    column = mutation.column
    if line[column : column + len(mutation.original)] != mutation.original:
        raise ValueError(f"mutation offset mismatch for {mutation.description}")
    lines[index] = line[:column] + mutation.replacement + line[column + len(mutation.original) :]
    return "".join(lines)

def collect(targets: list[str], limit: int) -> list[Mutation]:
    """Gather mutations across targets up to a global cap."""
    mutations: list[Mutation] = []
    for relative in targets:
        path = PROJECT_ROOT / relative
        source = path.read_text(encoding="utf-8")
        mutations.extend(discover_mutations(path, source))
        if len(mutations) >= limit:
            break
    return mutations[:limit]

def purge_bytecode() -> None:
    """Remove compiled caches so restored sources are always reloaded."""
    for cache in PROJECT_ROOT.rglob("__pycache__"):
        if ".venv" in cache.parts or ".git" in cache.parts:
            continue
        for artifact in cache.glob("*.pyc"):
            artifact.unlink(missing_ok=True)

def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
    """Record one script or link tag with its integrity attribute."""
    attributes = dict(attrs)
    if tag == "script" and attributes.get("src"):
        self.entries.append(
            {"kind": "script", "ref": _normalize_reference(str(attributes["src"])),
             "integrity": str(attributes.get("integrity", ""))}
        )
    if tag == "link" and attributes.get("href"):
        rel = str(attributes.get("rel", ""))
        href = _normalize_reference(str(attributes["href"]))
        if "stylesheet" in rel or href.endswith(".css"):
            self.entries.append(
                {"kind": "style", "ref": href,
                 "integrity": str(attributes.get("integrity", ""))}
            )

def _normalize_reference(ref: str) -> str:
    """Resolve a ``url_for('static', ...)`` expression to its served path."""
    match = re.search(
        r"url_for\(\s*['\"]static['\"]\s*,\s*filename\s*=\s*['\"]([^'\"]+)['\"]",
        ref,
    )
    if match is not None:
        return "/static/" + match.group(1)
    return ref

def load_manifest() -> dict:
    """Load and return the SRI manifest document."""
    return json.loads(MANIFEST_PATH.read_text(encoding="utf-8"))

def expected_for_reference(manifest: dict, ref: str) -> str | None:
    """Resolve the pinned integrity value for one template reference."""
    relative = ref[len("/static/"):] if ref.startswith("/static/") else ref
    pinned = manifest.get("assets", {}).get(relative)
    if pinned is not None:
        return pinned
    return manifest.get("cdn", {}).get(ref)

def integrity_attribute_ok(integrity: str, ref: str, expected: str) -> bool:
    """Accept a literal pin or the ``sri_integrity`` template expression."""
    if integrity == expected:
        return True
    for quote in ("'", '"'):
        if integrity == "{{ sri_integrity(" + quote + ref + quote + ") }}":
            return True
    return False

def check_local_hashes(manifest: dict, failures: list[str]) -> None:
    """Recompute every pinned local asset and record mismatches."""
    sys.path.insert(0, str(PROJECT_ROOT))
    from utils.integrity import compute_file_sri

    for relative, pinned in sorted(manifest.get("assets", {}).items()):
        path = STATIC_DIR / relative
        if not path.exists():
            failures.append("manifest lists missing file " + relative)
            continue
        actual = compute_file_sri(path, manifest.get("algorithm", "sha384"))
        if actual != pinned:
            failures.append("hash drift in " + relative)

def check_template_references(manifest: dict, failures: list[str]) -> None:
    """Require manifest-backed integrity on every template reference."""
    for template in sorted(TEMPLATES_DIR.glob("*.html")):
        parser = AssetReference()
        parser.feed(template.read_text(encoding="utf-8"))
        for entry in parser.entries:
            ref = entry["ref"]
            if not (ref.startswith("/static/") or ref.startswith("https://")):
                continue
            expected = expected_for_reference(manifest, ref)
            if expected is None:
                failures.append(template.name + " references unpinned " + ref)
            elif not integrity_attribute_ok(entry["integrity"], ref, expected):
                failures.append(template.name + " has stale integrity for " + ref)

def check_bucket_parity(failures: list[str]) -> None:
    """Require identical bucket tables in Python and JavaScript."""
    sys.path.insert(0, str(PROJECT_ROOT))
    from utils.padding import DEFAULT_FILE_BUCKETS, DEFAULT_MESSAGE_BUCKETS

    text = (STATIC_DIR / "js" / "qv-padding.js").read_text(encoding="utf-8")
    numbers = [int(value) for value in re.findall(r"\b\d{3,8}\b", text)]
    for bucket in DEFAULT_MESSAGE_BUCKETS:
        if bucket not in numbers:
            failures.append("qv-padding.js lacks message bucket " + str(bucket))
    for bucket in DEFAULT_FILE_BUCKETS:
        if bucket not in numbers:
            failures.append("qv-padding.js lacks file bucket " + str(bucket))

def set(self, key: str, value: Any, ttl: int = 3600) -> None:
    """Store a value in the cache with an optional TTL (seconds)."""
    self.client.setex(key, ttl, json.dumps(value))

def delete(self, key: str) -> None:
