def constant_time_compare(a: Optional[str], b: Optional[str]) -> bool:
    """Return True if the two strings match in constant time.

    A regular ``==`` leaks length and content-prefix information via
    short-circuit evaluation. This wraps :func:`hmac.compare_digest`
    which compares the whole input even when lengths differ.
    """
    if a is None or b is None:
        return False
    return hmac.compare_digest(a.encode("utf-8"), b.encode("utf-8"))

def verify_secret(secret: str, expected_hash: str) -> bool:
    """Verify a short-lived secret against its stored hash."""
    if not expected_hash:
        return False
    return constant_time_compare(hash_secret(secret), expected_hash)

def new_one_time_code(length: int = 6) -> str:
    """Return a cryptographically random numeric verification code."""
    return "".join(str(secrets.randbelow(10)) for _ in range(length))


# ---------------------------------------------------------------------------
# JSON CSRF protection
# ---------------------------------------------------------------------------

def _extract_csrf_token() -> str:
    """Return the CSRF token from the request header or body.

    Mirrors Flask-WTF's own lookup order so a client that sets either
    ``X-CSRFToken`` or ``X-CSRF-Token`` (the two spellings Flask-WTF accepts
    in ``WTF_CSRF_HEADERS``), or a ``csrf_token`` form/JSON field, is handled
    uniformly. The browser crypto in ``static/js/qv-crypto.js`` sends the
    ``X-CSRFToken`` header.
    """
    for header_name in ("X-CSRFToken", "X-CSRF-Token"):
        value = request.headers.get(header_name)
        if value:
            return value
    if request.is_json:
        body = request.get_json(silent=True) or {}
        token = body.get("csrf_token")
        if token:
            return token
    return request.form.get("csrf_token", "")

def wrapper(*args, **kwargs):
    if request.method in ("GET", "HEAD", "OPTIONS"):
        return view(*args, **kwargs)

    try:
        validate_csrf(_extract_csrf_token())
    except ValidationError:
        audit_event("csrf_rejection", method=request.method, path=request.path)
        return jsonify({"error": "CSRF token missing or invalid."}), 403

    return view(*args, **kwargs)

return wrapper

def _hash(*chunks: bytes) -> bytes:
    """Return the SHA-256 digest of the concatenated byte chunks."""
    digest = hashlib.sha256()
    for chunk in chunks:
        digest.update(chunk)
    return digest.digest()

def _hash_int(*chunks: bytes) -> int:
    """Return the SHA-256 digest of the concatenated chunks as an integer."""
    return int.from_bytes(_hash(*chunks), byteorder="big")

def compute_k() -> int:
    """Compute the SRP-6a multiplier parameter ``k = H(N | PAD(g))``."""
    return _hash_int(i2osp(N), i2osp(g))

def _key(username: str) -> str:
    """Return the Redis key for a username's pending SRP session."""
    return f"srp:session:{username}"

def database_path() -> str:
    """Return the SQLite database path from config, with a legacy fallback.

    Request-path code must never hard-code a database location: in tests and
    in multi-instance deployments the configured path is the only correct
    one, and a hard-coded path silently writes to (or reads from) the wrong
    file. Outside an application context, for standalone scripts, the
    ``QV_USERS_DB`` environment variable or the historical default is used.
    """
    if has_app_context():
        configured = current_app.config.get("SQLALCHEMY_DATABASE_PATH")
        if configured:
            return configured
    return os.environ.get("QV_USERS_DB", "instance/users.db")

